// Generated by GPT-6.2 Astra
`timescale 1ns/1ps
module layer_check #(
    parameter int WIDTH = 8,
    parameter int DEPTH = 16,
    parameter int CASES = 20,
    parameter FILE = "c0.mem"
)(
    input logic clk,
    input logic rst_n,
    input logic active,
    input logic start_case,
    input logic finish_case,
    input logic [31:0] sample_id,
    input logic we,
    input logic [$clog2(DEPTH)-1:0] addr,
    input logic [WIDTH-1:0] value
);
    logic [WIDTH-1:0] golden[0:CASES*DEPTH-1];
    integer n = 0;
    initial $readmemh(FILE, golden);
    always@(posedge clk)begin
        if(!rst_n || start_case)
            n = 0;
        if(active && we)begin
            if(addr !== n[$clog2(DEPTH)-1:0] || n >= DEPTH ||
                value !== golden[sample_id*DEPTH+n])
                $fatal(1, "%s case=%0d address=%0d expected=%h received=%h", FILE, sample_id, addr,
                       golden[sample_id*DEPTH+n], value);
            n = n + 1;
        end
        if(finish_case && n != DEPTH)
            $fatal(1, "%s incomplete writes %0d", FILE, n);
    end
endmodule

module npu_top_tb #(
    parameter int C0 = 12,
    parameter int C1 = 24,
