        .clk         (clk  ),
        .rst_n       (rst_n),
        .start       (start),
        .img_rd_en   (re   ),
        .img_rd_addr (addr ),
        .img_rd_data (pixel),
        .class_id    (id   ),
        .max_score   (score),
        .busy        (busy ),
        .done        (done )
    );
    always@(posedge clk)
        if(re)begin
            if(addr >= 3136)
                $fatal(1, "input address outside frame");
            pixel <= image[sample_id*3136+addr];
        end
    for(genvar i = 0; i < 4; i++)begin
        layer_check
        #(
            .CASES (CASES      ),
            .WIDTH (8 * C[i]   ),
            .DEPTH (W[i] * W[i]),
            .FILE  (CFILE[i]   )
        )
        u_check_conv(
            .clk         (clk                                                    ),
            .rst_n       (rst_n                                                  ),
            .active      (active                                                 ),
            .start_case  (start                                                  ),
            .finish_case (done                                                   ),
            .sample_id   (sample_id                                              ),
            .we          (u_npu_top.stage[i].u_npu_conv_multi_maxpool2d.conv_we  ),
            .addr        (u_npu_top.stage[i].u_npu_conv_multi_maxpool2d.conv_addr),
            .value       (u_npu_top.stage[i].u_npu_conv_multi_maxpool2d.conv_data)
        );
        if(i < 3)begin
            layer_check
            #(
