                .finish_case (done                                                      ),
                .sample_id   (sample_id                                                 ),
                .we          (u_npu_top.stage[i].u_npu_conv_multi_maxpool2d.feature_we  ),
                .addr        (u_npu_top.stage[i].u_npu_conv_multi_maxpool2d.feature_addr),
                .value       (u_npu_top.stage[i].u_npu_conv_multi_maxpool2d.feature_data)
            );
        end
    end
    layer_check
    #(
        .CASES (CASES       ),
        .WIDTH (32          ),
        .DEPTH (15          ),
        .FILE  ("scores.mem")
    )
    u_check_fc(
        .clk         (clk                  ),
        .rst_n       (rst_n                ),
        .active      (active               ),
        .start_case  (start                ),
        .finish_case (done                 ),
        .sample_id   (sample_id            ),
        .we          (u_npu_top.score_we   ),
        .addr        (u_npu_top.score_index),
        .value       (u_npu_top.score_value)
    );
    initial begin
        integer best, first_case, last_case, range_file;
        first_case = 0;
        last_case = CASES - 1;
