                $fatal(1, "final result case %0d", s);
            @(negedge clk);
            active = 0;
            $display("PASS RGB56 case=%0d cycles=%0d max=%0d", s, cycles, score);
        end
        if(CASES == 20 && first_case == 0 && last_case == CASES - 1)
            $display(
